CREATE VIEW purchase_standalone_support_pending_owners AS SELECT DISTINCT c.user_id AS owner_id,p.environment FROM purchase_pending_changes p JOIN complete_plan_changes c ON c.organization_id=p.organization_id JOIN organizations o ON o.organization_id=c.organization_id AND o.created_by_user_id=c.user_id JOIN organization_members m ON m.organization_id=o.organization_id AND m.user_id=c.user_id AND m.role='owner' AND m.revoked_at IS NULL WHERE NOT EXISTS(SELECT 1 FROM account_session_policy a WHERE a.user_id=c.user_id AND a.deleted_at IS NOT NULL);
--> statement-breakpoint
CREATE VIEW purchase_standalone_support_locks AS SELECT i.owner_id,f.environment,w.id AS workspace_id FROM purchase_intent_footprints f JOIN purchase_intents i ON i.intent_id=f.intent_id AND i.environment=f.environment AND i.product='support' AND i.organization_id IS NULL AND i.workspace_id=f.scope_id JOIN support_workspaces w ON w.id=i.workspace_id AND w.owner_id=i.owner_id WHERE f.scope_kind='workspace' AND f.entitlement='support' AND f.released_at IS NULL AND NOT EXISTS(SELECT 1 FROM support_gestion_links l WHERE l.workspace_id=w.id) UNION ALL SELECT r.owner_id,r.environment,w.id FROM stripe_support_purchase_requests r JOIN support_workspaces w ON w.id=r.workspace_id AND w.owner_id=r.owner_id WHERE r.organization_id IS NULL AND r.closed_at IS NULL AND NOT EXISTS(SELECT 1 FROM support_gestion_links l WHERE l.workspace_id=w.id) UNION ALL SELECT w.owner_id, CASE WHEN substr(c.session_id,1,8)='cs_test_' THEN 'TEST' WHEN substr(c.session_id,1,8)='cs_live_' THEN 'PRODUCTION' ELSE p.environment END ,w.id FROM support_checkouts c JOIN support_workspaces w ON w.id=c.workspace_id CROSS JOIN (SELECT 'TEST' AS environment UNION ALL SELECT 'PRODUCTION') p WHERE (c.session_id IS NULL OR c.expires_at>unixepoch()) AND NOT EXISTS(SELECT 1 FROM support_gestion_links l WHERE l.workspace_id=w.id);
--> statement-breakpoint
CREATE TRIGGER purchase_standalone_support_change_insert BEFORE INSERT ON complete_plan_changes WHEN NEW.state IN ('preparing','scheduled') BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM purchase_standalone_support_locks s WHERE s.owner_id=NEW.user_id AND (coalesce(json_type( CASE WHEN json_valid(NEW.source_json) THEN NEW.source_json ELSE '{}' END ,'$.live'),'null') NOT IN ('true','false') OR s.environment= CASE json_type( CASE WHEN json_valid(NEW.source_json) THEN NEW.source_json ELSE '{}' END ,'$.live') WHEN 'true' THEN 'PRODUCTION' ELSE 'TEST' END )) THEN RAISE(ABORT,'purchase_change_standalone_support') END ; END ;
--> statement-breakpoint
CREATE TRIGGER purchase_standalone_support_change_update BEFORE UPDATE ON complete_plan_changes WHEN NEW.state IN ('preparing','scheduled') BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM purchase_standalone_support_locks s WHERE s.owner_id=NEW.user_id AND (coalesce(json_type( CASE WHEN json_valid(NEW.source_json) THEN NEW.source_json ELSE '{}' END ,'$.live'),'null') NOT IN ('true','false') OR s.environment= CASE json_type( CASE WHEN json_valid(NEW.source_json) THEN NEW.source_json ELSE '{}' END ,'$.live') WHEN 'true' THEN 'PRODUCTION' ELSE 'TEST' END )) THEN RAISE(ABORT,'purchase_change_standalone_support') END ; END ;
--> statement-breakpoint
CREATE TRIGGER purchase_standalone_support_request_insert BEFORE INSERT ON stripe_support_purchase_requests WHEN NEW.organization_id IS NULL BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM purchase_standalone_support_pending_owners p WHERE p.owner_id=NEW.owner_id AND p.environment=NEW.environment) THEN RAISE(ABORT,'stripe_support_purchase_conflict') END ; END ;
--> statement-breakpoint
CREATE TRIGGER purchase_standalone_support_intent_insert BEFORE INSERT ON purchase_intents WHEN NEW.product='support' AND NEW.organization_id IS NULL BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM purchase_standalone_support_pending_owners p JOIN support_workspaces w ON w.id=NEW.workspace_id AND w.owner_id=p.owner_id WHERE p.owner_id=NEW.owner_id AND p.environment=NEW.environment) THEN RAISE(ABORT,'purchase_change_standalone_support') END ; END ;
--> statement-breakpoint
CREATE TRIGGER purchase_standalone_support_footprint_insert BEFORE INSERT ON purchase_intent_footprints WHEN NEW.scope_kind='workspace' AND NEW.entitlement='support' BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM purchase_intents i JOIN support_workspaces w ON w.id=NEW.scope_id AND w.owner_id=i.owner_id JOIN purchase_standalone_support_pending_owners p ON p.owner_id=i.owner_id AND p.environment=NEW.environment WHERE i.intent_id=NEW.intent_id AND i.product='support' AND i.organization_id IS NULL) THEN RAISE(ABORT,'purchase_change_standalone_support') END ; END ;
--> statement-breakpoint
CREATE TRIGGER purchase_standalone_support_dispatch BEFORE UPDATE OF state ON purchase_intents WHEN NEW.product='support' AND NEW.organization_id IS NULL AND (NEW.state='dispatched' OR (OLD.state='uncertain' AND NEW.state='uncertain')) BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM purchase_standalone_support_pending_owners p JOIN support_workspaces w ON w.id=NEW.workspace_id AND w.owner_id=p.owner_id WHERE p.owner_id=NEW.owner_id AND p.environment=NEW.environment) THEN RAISE(ABORT,'purchase_change_standalone_support') END ; END ;
